// Mutant: Utility method to check if a number is negative
private boolean isNegativeNumber(String num) {
    return Integer.parseInt(num) < 0;
}

// Utility method to check if a string is a positive number
private boolean isPositiveNumber(String str) {
    try {
        return Double.parseDouble(str) >= 0;
    } catch (NumberFormatException e) {
        return false;
    }
}
